  INSERT INTO public.jarvis_insights (type, severity, title, description, entity_id, asset_id, metadata) VALUES ('patrimonial', 'medium', 'Concentração de 42% do patrimônio em ativos rurais no PR', 'R$ 81,2M em quatro propriedades paranaenses. Risco climático e de preço de commodities correlacionados.', v_agro, NULL, '{"percentual":42,"valor_brl":81200000}'::jsonb);
  INSERT INTO public.jarvis_insights (type, severity, title, description, entity_id, asset_id, metadata) VALUES ('compliance', 'medium', 'CND Federal vence em 12 dias', 'A certidão da Holding é exigida em três processos de licitação abertos. Renovação leva até 5 dias úteis.', v_holding, NULL, '{"dias_restantes":12,"processos":3}'::jsonb);
  INSERT INTO public.jarvis_insights (type, severity, title, description, entity_id, asset_id, metadata) VALUES ('patrimonial', 'low', 'Terreno de Arapongas com potencial de incorporação', '32.000 m² em zona industrial com FCA favorável. Estudo preliminar indica VGV de R$ 41M em galpões logísticos.', v_re, (SELECT id FROM public.assets WHERE name = 'Terreno Industrial Arapongas' AND entity_id = v_re LIMIT 1), '{"area_m2":32000,"vgv_estimado_brl":41000000}'::jsonb);
  INSERT INTO public.jarvis_action_plans (insight_id, title, due_date, priority, status, impact_analysis, suggested_resolution) VALUES (v_insight, 'Contratar recertificação INCRA da matrícula 12.884', (now() + interval '15 days'), 'P1', 'in_progress', 'Libera R$ 48,5M em garantia real para crédito rural e destrava a averbação da área.', 'Acionar o topógrafo credenciado, reapresentar o SIGEF e averbar o memorial descritivo no registro de imóveis de Apucarana.');
