  INSERT INTO public.jarvis_action_plans (insight_id, title, due_date, priority, status, impact_analysis, suggested_resolution) VALUES (v_insight, 'Renovar laudo ANAC do H130', (now() + interval '7 days'), 'P1', 'pending', 'Elimina exposição de R$ 9,8M em ativo sem cobertura válida.', 'Agendar inspeção em oficina homologada e emitir novo CA (certificado de aeronavegabilidade).');
  INSERT INTO public.jarvis_action_plans (insight_id, title, due_date, priority, status, impact_analysis, suggested_resolution) VALUES (v_insight, 'Emitir nova CND Federal da Holding', (now() + interval '10 days'), 'P2', 'pending', 'Mantém elegibilidade em 3 processos licitatórios ativos.', 'Baixar certidão no e-CAC e arquivar no cofre digital com alerta de 90 dias.');
