-- =============================================================================
-- PATRIUM OS — dataset de demonstração
-- GERADO AUTOMATICAMENTE por scripts/generate-seed-sql.ts
-- Não edite à mão: altere src/lib/demo/demoData.ts e rode o gerador.
--
-- Uso (service_role / psql, após criar o usuário demo@patrium.os em Authentication):
--   psql "$SUPABASE_DB_URL" -v ON_ERROR_STOP=1 -f supabase/seed.sql
--   ou: supabase db reset   (o CLI roda supabase/seed.sql automaticamente)
-- =============================================================================

DO $$
DECLARE
  v_user uuid;
  v_holding uuid;
  v_agro uuid;
  v_re uuid;
  v_asset uuid;
  v_insight uuid;
  v_member uuid;
BEGIN
  SELECT id INTO v_user FROM auth.users WHERE email = 'demo@patrium.os';
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Usuário % não encontrado em auth.users. Crie a conta primeiro.', 'demo@patrium.os';
  END IF;

  -- Limpa o tenant alvo (ordem respeita as FKs)
  DELETE FROM public.jarvis_action_plans WHERE insight_id IN (SELECT id FROM public.jarvis_insights WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user));
  DELETE FROM public.jarvis_insights   WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.jarvis_health_scores WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.transactions WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.risks        WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.documents    WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.assets       WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.entity_shares WHERE entity_id IN (SELECT id FROM public.entities WHERE owner_user_id = v_user);
  DELETE FROM public.members  WHERE owner_user_id = v_user;
  DELETE FROM public.entities WHERE owner_user_id = v_user;

  -- Holdings

  -- Sócios e conselho

  -- Participações societárias
  SELECT id INTO v_member FROM public.members WHERE email = 'roberto@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'roberto@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'helena@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'helena@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'marina@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'marina@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'rafael@alencar.com.br' AND owner_user_id = v_user LIMIT 1;
  SELECT id INTO v_member FROM public.members WHERE email = 'rafael@alencar.com.br' AND owner_user_id = v_user LIMIT 1;

  -- Ativos

  -- Documentos

  -- Riscos

  -- Transações financeiras

  -- Insights do JARVIS

  -- Planos de ação
  SELECT id INTO v_insight FROM public.jarvis_insights WHERE title = 'Georreferenciamento vencido trava a Fazenda Santa Fé' LIMIT 1;
  SELECT id INTO v_insight FROM public.jarvis_insights WHERE title = 'Sobreposição de reserva legal na Rio Verde' LIMIT 1;
  SELECT id INTO v_insight FROM public.jarvis_insights WHERE title = 'Aeronave H130 sem laudo de aeronavegabilidade' LIMIT 1;
  SELECT id INTO v_insight FROM public.jarvis_insights WHERE title = 'CND Federal vence em 12 dias' LIMIT 1;
  SELECT id INTO v_insight FROM public.jarvis_insights WHERE title = 'Terreno de Arapongas com potencial de incorporação' LIMIT 1;

  -- Fornecedores

  -- Processos jurídicos

  -- Histórico de health score (12 meses)

  RAISE NOTICE 'PATRIUM OS: dataset de demonstração aplicado ao usuário %.', 'demo@patrium.os';
END $$;
